WITH parsed AS (SELECT id, customer_id, created_at, items, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, FORALL(items, i -> i.qty <= 5) AS all_small_qty FROM carts) SELECT *, SUM(max_item_price) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_sum_max_item_price, COUNT(max_item_price) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_count_max_item_price, MIN(max_item_price) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_min_max_item_price, MAX(max_item_price) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) last7_max_max_item_price FROM parsed;
